from pathlib import Path

APP=Path('dist/app.js')
INDEX=Path('dist/index.html')
HUD_JS=Path('dist/technical-hud-r34.js')
HUD_CSS=Path('dist/technical-hud-r34.css')

app=APP.read_text(encoding='utf-8')

def replace_once(text, old, new, label):
    if new in text:
        return text
    if old not in text:
        raise SystemExit(f'R34 patch point not found: {label}')
    return text.replace(old,new,1)

app=replace_once(app,"showAll:()=>ggQuickFilter('all')","showAll:()=>ggQuickFilter('all'),\n getViewState:()=>viewState(),\n frameSection:()=>frameSection()",'viewer api')
app=replace_once(app,"camera.position.fromArray(s.position);controls.target.fromArray(s.target);","if(Array.isArray(s.position)&&s.position.length>=3)camera.position.fromArray(s.position);if(Array.isArray(s.target)&&s.target.length>=3)controls.target.fromArray(s.target);",'safe restore')
app=replace_once(app,"offset=Math.max(localScale*.2,max*.012,.025),labelHeight=Math.max(localScale*(mobileLayout()?.14:.11),max*.007,.024);","offset=Math.max(localScale*(mobileLayout()?.32:.24),max*(mobileLayout()?.025:.018),mobileLayout()?.04:.03),labelHeight=Math.max(localScale*(mobileLayout()?.24:.18),max*(mobileLayout()?.024:.016),mobileLayout()?.05:.035);",'dimension labels')
old_frame="""const center=f.n.clone().multiplyScalar((f.lo[0]+f.hi[0])/2).addScaledVector(f.u,(f.lo[1]+f.hi[1])/2).addScaledVector(f.v,(f.lo[2]+f.hi[2])/2);
 const cross=Math.max(f.hi[1]-f.lo[1],f.hi[2]-f.lo[2],.1),length=Math.max(f.hi[0]-f.lo[0],cross),span=Math.max(length,cross),aspect=$('canvas').clientWidth/$('canvas').clientHeight;
 const view=f.n.clone().multiplyScalar(1.12).addScaledVector(f.u,.46).addScaledVector(f.v,.3).normalize();camera.up.copy(f.v);camera.position.copy(center).addScaledVector(view,span*2.05+1);controls.target.copy(center);camera.userData.span=span*1.28/Math.min(aspect,1);camera.zoom=1;"""
new_frame="""const center=f.n.clone().multiplyScalar(s.at).addScaledVector(f.u,(f.lo[1]+f.hi[1])/2).addScaledVector(f.v,(f.lo[2]+f.hi[2])/2);
 const sectionW=Math.max(f.hi[1]-f.lo[1],.05),sectionH=Math.max(f.hi[2]-f.lo[2],.05),cross=Math.max(sectionW,sectionH,.1),length=Math.max(f.hi[0]-f.lo[0],cross),aspect=Math.max($('canvas').clientWidth/$('canvas').clientHeight,.35),sectionSpan=Math.max(sectionH*1.85,sectionW/aspect*1.85,cross*1.55,mobileLayout()?.42:.32);
 const view=f.n.clone().multiplyScalar(1).addScaledVector(f.u,.07).addScaledVector(f.v,.04).normalize();camera.up.copy(f.v);camera.position.copy(center).addScaledVector(view,Math.max(sectionSpan*3.2,1.1));controls.target.copy(center);camera.userData.span=sectionSpan;camera.zoom=1;"""
